//! V: `azul/azul.v` (module `azul`, generated by `doc/src/codegen/v2/lang_v`).
//!
//! Spellings: every C function is declared `fn C.AzFoo_bar(..)` and called
//! through the global `C.` namespace (`C.AzCssProperty_textColor(..)`,
//! variant constructors `C.AzLayoutWidth_px(..)`), types are `azul.Az*`,
//! enums `azul.AzLayoutDisplay.Flex`, structs and unions are struct / union
//! literals (`azul.AzColorU{ r: 255, .. }`,
//! `azul.AzLayoutWidthValue{ Exact: azul.AzLayoutWidthValueVariant_Exact{ tag: 6, payload: .. } }`,
//! V keywords get `_`), strings `azul.az_str('..')`.
//!
//! Calls and literals nest; a Vec needs an addressable array
//! ([`super::linear`]): `mut t1 := [n]azul.AzX{}`, filled element by
//! element, then `C.AzXVec_copyFromPtr(unsafe { &t1[0] }, n)`.

use alloc::{
    format,
    string::{String, ToString},
    vec,
    vec::Vec,
};

use super::linear::{item_blocker, linear_comments, lower_to_statements, LinearSyntax};
use crate::codegen::{
    ir::{snake_to_lower_camel, Item, Module, Prim},
    lang::{escape_quoted, unicode_u4, variant_ctor_method},
    CodegenBackend, GeneratedFile,
};

/// The V printer.
#[derive(Debug, Copy, Clone, Default)]
pub struct V;

/// `is_v_keyword` of `lang_v/mod.rs`.
const KEYWORDS: &[&str] = &[
    "as", "asm", "assert", "atomic", "break", "const", "continue", "defer", "else", "enum",
    "false", "fn", "for", "go", "goto", "if", "import", "in", "interface", "is", "isreftype",
    "lock", "match", "module", "mut", "none", "or", "pub", "return", "rlock", "select", "shared",
    "sizeof", "spawn", "static", "struct", "true", "type", "typeof", "union", "unsafe",
    "volatile", "__global", "__offsetof",
];

fn ident(name: &str) -> String {
    if KEYWORDS.contains(&name) {
        format!("{name}_")
    } else {
        name.to_string()
    }
}

fn apply(f: &str, args: &[String]) -> String {
    format!("{f}({})", args.join(", "))
}

fn v_string(s: &str) -> String {
    let mut out = String::from("'");
    out.push_str(&escape_quoted(s, &['\'', '$'], &unicode_u4).replace("\\\"", "\""));
    out.push('\'');
    out
}

impl LinearSyntax for V {
    fn int(&self, value: i128, _ty: Prim) -> String {
        value.to_string()
    }

    fn float(&self, text: &str, ty: Prim) -> String {
        let t = if ty == Prim::F64 { "f64" } else { "f32" };
        match text {
            "nan" => format!("{t}(math.nan())"),
            "inf" => format!("{t}(math.inf(1))"),
            "-inf" => format!("{t}(math.inf(-1))"),
            _ => text.to_string(),
        }
    }

    fn boolean(&self, b: bool) -> String {
        b.to_string()
    }

    fn clike(&self, ty: &str, variant: &str) -> String {
        format!("azul.Az{ty}.{}", ident(variant))
    }

    fn type_name(&self, ty: &str) -> String {
        format!("azul.Az{ty}")
    }

    fn array_type(&self, elem: &str, n: usize) -> String {
        format!("[{n}]azul.Az{elem}{{}}")
    }

    fn call(&self, target: &str, class: &str, method: &str, args: &[String]) -> Vec<String> {
        let e = self.call_expr(class, method, args).unwrap_or_default();
        vec![format!("{target} = {e}")]
    }

    fn variant_call(&self, target: &str, ty: &str, variant: &str, args: &[String]) -> Vec<String> {
        let e = self.variant_expr(ty, variant, args).unwrap_or_default();
        vec![format!("{target} = {e}")]
    }

    fn union(
        &self,
        target: &str,
        ty: &str,
        variant: &str,
        tag: usize,
        payload: Option<&str>,
    ) -> Vec<String> {
        let e = self.union_expr(ty, variant, tag, payload).unwrap_or_default();
        vec![format!("{target} = {e}")]
    }

    fn set_field(&self, target: &str, _ty: &str, field: &str, value: &str) -> String {
        format!("{target}.{} = {value}", ident(field))
    }

    fn set_elem(&self, arr: &str, index: usize, value: &str) -> String {
        format!("{arr}[{index}] = {value}")
    }

    fn vec_from_array(&self, target: &str, ty: &str, elem: &str, arr: &str, count: &str) -> Vec<String> {
        let e = self.vec_expr(ty, elem, arr, count).unwrap_or_default();
        vec![format!("{target} = {e}")]
    }

    fn vec_empty(&self, target: &str, ty: &str) -> Vec<String> {
        vec![format!("{target} = C.Az{ty}_create()")]
    }

    fn string(&self, target: &str, s: &str) -> Vec<String> {
        vec![format!("{target} = azul.az_str({})", v_string(s))]
    }

    fn call_expr(&self, class: &str, method: &str, args: &[String]) -> Option<String> {
        Some(apply(&format!("C.Az{class}_{}", snake_to_lower_camel(method)), args))
    }

    fn variant_expr(&self, ty: &str, variant: &str, args: &[String]) -> Option<String> {
        Some(apply(&format!("C.Az{ty}_{}", variant_ctor_method(variant)), args))
    }

    fn union_expr(&self, ty: &str, variant: &str, tag: usize, payload: Option<&str>) -> Option<String> {
        let v = ident(variant);
        let inner = match payload {
            Some(p) => format!("tag: {tag}, payload: {p}"),
            None => format!("tag: {tag}"),
        };
        Some(format!("azul.Az{ty}{{ {v}: azul.Az{ty}Variant_{v}{{ {inner} }} }}"))
    }

    fn struct_expr(&self, ty: &str, fields: &[(String, String)]) -> Option<String> {
        if fields.is_empty() {
            return Some(format!("azul.Az{ty}{{}}"));
        }
        let fields: Vec<String> = fields
            .iter()
            .map(|(k, v)| format!("{}: {v}", ident(k)))
            .collect();
        Some(format!("azul.Az{ty}{{ {} }}", fields.join(", ")))
    }

    fn string_expr(&self, s: &str) -> Option<String> {
        Some(format!("azul.az_str({})", v_string(s)))
    }

    fn vec_expr(&self, ty: &str, _elem: &str, arr: &str, count: &str) -> Option<String> {
        Some(format!("C.Az{ty}_copyFromPtr(unsafe {{ &{arr}[0] }}, {count})"))
    }

    fn vec_empty_expr(&self, ty: &str) -> Option<String> {
        Some(format!("C.Az{ty}_create()"))
    }
}

fn item_fn(item: &Item) -> (bool, String) {
    let name = item.name.snake();
    if let Some(reason) = item_blocker(&V, item) {
        return (
            false,
            format!("// {name}: not expressible with the V bindings: {reason}\n"),
        );
    }
    let st = lower_to_statements(&V, &item.value);
    let mut out = String::new();
    for line in linear_comments(item, &st) {
        out.push_str(&format!("// {line}\n"));
    }
    out.push_str(&format!("fn {name}() azul.Az{} {{\n", item.ty));
    for (n, t) in &st.decls {
        if t.starts_with('[') {
            out.push_str(&format!("\tmut {n} := {t}\n"));
        } else {
            out.push_str(&format!("\tmut {n} := {t}{{}}\n"));
        }
    }
    for s in &st.body {
        out.push_str(&format!("\t{s}\n"));
    }
    out.push_str(&format!("\treturn {}\n}}\n", st.result));
    (true, out)
}

fn uses_nonfinite(m: &Module) -> bool {
    super::uses_nonfinite_float(m)
}

impl CodegenBackend for V {
    fn lang(&self) -> &'static str {
        "v"
    }

    fn aliases(&self) -> &'static [&'static str] {
        &["vlang"]
    }

    fn display_name(&self) -> &'static str {
        "V"
    }

    fn extension(&self) -> &'static str {
        "v"
    }

    fn emit_module(&self, m: &Module) -> String {
        let mut out = String::from(
            "// Generated by azul-css codegen (V). Do not edit by hand.\nmodule main\n\nimport \
             azul\n",
        );
        if uses_nonfinite(m) {
            out.push_str("import math\n");
        }
        for item in &m.items {
            out.push('\n');
            out.push_str(&item_fn(item).1);
        }
        out
    }

    fn emit_project_files(&self, m: &Module) -> Vec<GeneratedFile> {
        let mut main = String::from(
            "// Copy target/codegen/azul.v to ./azul/ and libazul here, then: v run .\nmodule \
             main\n\nfn main() {\n",
        );
        for item in m.items.iter().filter(|i| item_fn(i).0) {
            let name = item.name.snake();
            main.push_str(&format!(
                "\t{name}_value := {name}()\n\tprintln('{name}: ${{{name}_value.len}} \
                 properties')\n"
            ));
        }
        main.push_str("}\n");
        vec![
            GeneratedFile {
                path: "styles.v".to_string(),
                contents: self.emit_module(m),
            },
            GeneratedFile {
                path: "main.v".to_string(),
                contents: main,
            },
        ]
    }
}
